  .planner-nav-controls>button,.planner-nav-controls>.restore-label{width:100%;margin:0;padding:9px 10px;border-radius:9px;background:#f6fafc;border:1px solid #d6e2e9;color:#506b82;text-align:left;font-size:11px;font-weight:800}
  .planner-nav-controls>button:hover,.planner-nav-controls>.restore-label:hover{background:#edf5f8;color:#3e5d75}
  .planner-nav-controls>.planner-balance{background:#b9d5ec;border-color:#aacbe5;color:#315879}
  .planner-nav-controls>.planner-optimize{background:#bfe0d1;border-color:#add5c3;color:#356a55}
  .planner-control-divider{height:1px;background:#cfdee7;margin:3px 0}
  .planner-nav-controls>.planner-delete-day{background:#f3dddd;border-color:#e9c7c7;color:#8d5555}
  .planner-nav-controls>.planner-delete-all{background:#edd0d0;border-color:#dfbcbc;color:#814a4a}
  #planner.active{height:calc(100dvh - 110px);min-height:520px;overflow:hidden}
  #planner.active .routes{height:100%;align-items:stretch}
  #planner.active .route{height:100%;min-height:0;display:flex;flex-direction:column;overflow:hidden}
  #planner.active .route-head{flex:0 0 auto}
  #planner.active .map{flex:0 0 230px;height:230px;min-height:230px}
  #planner.active .route-list{flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding-bottom:70px}
  #planner.active #dayWarning{position:absolute;left:16px;right:16px;top:8px;z-index:150;box-shadow:0 8px 22px #62788720}
}

@media(max-width:1023px){
  #plannerMobileControlHost>.planner-nav-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-bottom:12px;padding:10px;background:#fffefd;border:1px solid var(--border);border-radius:14px}
  #plannerMobileControlHost .planner-control-title,#plannerMobileControlHost .planner-nav-date,#plannerMobileControlHost .planner-control-divider{grid-column:1/-1}
  #plannerMobileControlHost .planner-nav-date{display:grid;grid-template-columns:34px minmax(0,1fr) 34px;gap:6px}
  #plannerMobileControlHost .planner-nav-controls>button,#plannerMobileControlHost .planner-nav-controls>.restore-label{margin:0;padding:9px 8px;font-size:11px;text-align:center;border-radius:9px;background:#edf4f8;color:#527493;border:1px solid #dce8ee}
  #plannerMobileControlHost .planner-nav-controls>.planner-balance{background:#b9d5ec;color:#315879}
  #plannerMobileControlHost .planner-nav-controls>.planner-optimize{background:#bfe0d1;color:#356a55}
  #plannerMobileControlHost .planner-nav-controls>.planner-delete-day,#plannerMobileControlHost .planner-nav-controls>.planner-delete-all{color:#8d5555;background:#f3dddd;border-color:#e9c7c7}
}

:root{--navy:#647f96;--blue:#7da8cf;--blue-2:#6f99c0;--sky:#edf5fb;--bg:#f6f7f6;--card:#fffefd;--ink:#30465a;--muted:#788a98;--green:#78b69d;--red:#d58d8d;--amber:#d2ad78;--purple:#a796bc;--border:#dfe7ea}
body{background:#f6f7f6;color:var(--ink)}
.topbar{background:#fffdfb;border-bottom-color:#e3e8ea;box-shadow:0 3px 14px #687d8b10}.topbar h1{color:#405a70}.topbar small{color:#7e8d98}.header-search input{background:#f8fafb;border-color:#e0e7eb}.ghost{border-color:#dde5e9;color:#536b7d;background:#fff}
.route,.panel,.card{background:#fffefd}.route-head{background:#fffefd}.route-head h2 input{color:#405a70}.route-list{background:#f4f7f8}.bubble{background:#fffefd;border-color:#e0e7ea}.bubble-main-line{background:#f7f9f9}.order-number-line,.tag{background:#eaf3fa}.bubble-actions button{background:#edf4f8;color:#527493;border-color:#dce8ee}
.complete-button{background:#edf7f2;color:#5b947d;border-color:#b9d9cb}.trash{background:#faeeee;color:#b96565}.notice{background:#eef5f7;border-color:#d7e5e9;color:#58717f}
@media(min-width:1024px){nav{background:#e8f0f5;border-right:1px solid #d6e1e8;box-shadow:3px 0 16px #60788b0e}nav::before{color:#46627a}.nav{color:#5e7487}.nav:hover{background:#dbe8f0;color:#405d75}.nav.active{background:#bfd8eb;color:#315777}}

.auth-screen{background:linear-gradient(145deg,#dcebf3,#dfeee8)}.auth-card{background:#fffefd;box-shadow:0 26px 70px #5d73852b}.auth-logo{background:linear-gradient(135deg,#8fb2cd,#91c1ad);color:#fff}
.driver-portal-header{background:linear-gradient(135deg,#88aeca,#88bca5);box-shadow:0 6px 20px #526b7c22}.driver-date-tabs{background:#fffefcf2}.driver-date-tabs button{background:#e8eff2;color:#617685}.driver-date-tabs button.active{background:#9abbd3;color:#35536b}
.mobile-user-bubble{background:#fffefd;box-shadow:0 6px 18px #62788712}.mobile-sequence{background:#9bbbd2;color:#35526a}.mobile-stop{background:#eff5f7}.mobile-stop.drop{background:#f2eff6}
dialog{background:#fffefd;box-shadow:0 28px 76px #6278872e}dialog::backdrop{background:#536b7c4f}.close,.sticky-dialog-head{background:#fffefd}.tab{background:#e9eff2;color:#617685}.tab.active{background:#a9c3d6;color:#35546b}
.table-wrap,.v38-preview-card,.group-order-section{background:#fffefd}.backlog-table th{background:#8daabd;color:#304b60}.v38-dropzone{background:#f2f7f7;border-color:#b9ced4}.martin-import .v38-dropzone{background:#f5f1f7;border-color:#cbbdd6}
.v38-remove,.trash{background:#f8e8e8;color:#a96767}.v38-drop-status.warn,.v38-status.warn,.tag.warn{background:#f7eddc;color:#96733f}.master-highlight{background:#edf5f7;border-color:#b9d2dc}.drop-highlight{background:#eef6f0;border-color:#b9d7c5}.supplier-location-select{background:#f7f1e4;border-color:#dac9a7}.master-warning{background:#f8e9e9;color:#946060;border-color:#e3c4c4}
.item-note-preview,.missing-qty-wrap{background:#f8f1e5;border-color:#e4d2b5;color:#7f6847!important}.dropoff-summary{background:linear-gradient(135deg,#f7f1e6,#f2e8d8);border-color:#d9c29c;box-shadow:0 6px 18px #7d6b5112}.route[data-driver="mario"] .dropoff-summary{background:linear-gradient(135deg,#edf5f9,#e2eff5);border-color:#a8cadb}.route[data-driver="patrik"] .dropoff-summary{background:linear-gradient(135deg,#f3eff7,#ebe4f2);border-color:#c7b8d7}.route[data-driver="martin"] .dropoff-summary{background:linear-gradient(135deg,#eff7ef,#e5f1e5);border-color:#b8d2b4}
.mobile-user-actions .camera-action,.camera-button{background:linear-gradient(135deg,#a99abb,#b8a8c7)}.driver-focus-shell,.driver-focus-route{background:#f5f7f6}.driver-focus-close{background:#edf2f3;color:#526b7d}.review-error{border-color:#dda9a9!important;background:#faeeee!important}.search-result:hover{border-color:#a7c3d6}.bubble.search-highlight{border-color:#d8bb7d;box-shadow:0 0 0 6px #f3dfae80,0 10px 24px #8a744326}
.auth-mode-tabs button{background:#e9eff2;color:#566f82}.auth-mode-tabs button.active{background:#a9c3d6;color:#35546b}.online-sync-status{background:#e8f4ee;color:#557f69}.online-sync-status[data-state="syncing"],.online-sync-status[data-state="loading"]{background:#f7efdF;color:#8a734f}.online-sync-status[data-state="error"]{background:#f8e8e8;color:#986060}.transfer-action{background:#a99abb!important}.incoming-transfers{background:#f7f1df;border-color:#e1d2aa}.transfer-admin-row.status-pending{border-left-color:#d2ad78}.transfer-admin-row.status-accepted{border-left-color:#78b69d}.transfer-admin-row.status-rejected,.transfer-admin-row.status-cancelled{border-left-color:#d58d8d}

/* V49 – kattintható felrakási térkép és buborékfókusz */
.v49-map-marker{background:transparent!important;border:0!important}
.v49-map-marker span{display:grid;place-items:center;width:32px;height:32px;border:2px solid #fff;border-radius:50%;background:#86afca;color:#fff;box-shadow:0 4px 12px #526d8040;font-size:11px;font-weight:950;cursor:pointer}
.v49-pickup-marker span{background:#86afca}
.map-route-highlight{position:relative;z-index:5;outline:3px solid #d5b979!important;outline-offset:3px;box-shadow:0 0 0 7px #f1dfb45c,0 10px 24px #6d654326!important;transition:box-shadow .2s ease,outline-color .2s ease}

/* V55 – felrakási sorszám a térképen */
.pickup-pin{background:none;border:none}
.pickup-pin span{display:flex;align-items:center;justify-content:center;width:26px;height:26px;
  border-radius:50%;background:#647f96;color:#fff;font:600 13px/1 system-ui,sans-serif;
  border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.4)}

/* V56 – kompakt felrakósorok a Nézet ablakban */
.driver-focus-route .v56-row-block{margin:0}
.v56-row{display:flex;align-items:center;gap:10px;padding:7px 12px;border-bottom:.5px solid #d9d5c9;
  background:#fff;position:relative}
.v56-row.done{opacity:.55}
.v56-row.has-long{border-left:3px solid #ba7517}
.v56-row-block.pinned-block .v56-row{border-left:3px solid #534ab7}
.v56-row.resolved-backlog{background:#f4f2ec}
.v56-drag{cursor:grab;color:#9a978d;font-size:15px;flex:none;line-height:1}
.v56-index{flex:none;width:22px;height:22px;border-radius:50%;background:#e6f1fb;color:#0c447c;
  font-size:12px;display:flex;align-items:center;justify-content:center}
.v56-main{flex:1;min-width:0}
.v56-line-top{font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.45}
.v56-line-top b{font-weight:600}
.v56-addr{color:#6b675d;font-weight:400}
.v56-line-drop{color:#1c1b18}
.v56-extra{color:#6b675d;font-size:12px;margin-left:6px}
.v56-chip{font-size:11px;color:#5f5e5a;border:.5px solid #d3d1c7;border-radius:6px;padding:1px 5px;margin-left:5px}
.v56-chip-warn{color:#854f0b;background:#faeeda;border-color:#efc98f}
.v56-items-btn{flex:none;height:28px;padding:0 9px;font-size:12px;border:.5px solid #cfcbbf;
  background:#fff;border-radius:6px;cursor:pointer;color:#2c2c2a}
.v56-items-btn:hover{background:#f1efe8}
.v56-items-btn.open{background:#e6f1fb;border-color:#85b7eb}
.v56-items{padding:6px 12px 10px 54px;background:#faf9f5;border-bottom:.5px solid #d9d5c9}
.v56-item-row{display:flex;justify-content:space-between;gap:12px;font-size:12px;padding:3px 0;border-bottom:.5px solid #e6e3d9}
.v56-item-row:last-child{border-bottom:0}
.v56-item-qty{color:#6b675d;white-space:nowrap}
.v56-item-empty{color:#8a877d}
.v56-forced-drop{font-size:12px;color:#854f0b;background:#faeeda;padding:5px 12px 5px 54px;border-bottom:.5px solid #d9d5c9}
.v56-drop-block{margin:0 0 8px}
.v56-drop-block:last-child{margin-bottom:0}
.v56-drop-head{display:flex;justify-content:space-between;gap:12px;font-size:13px;padding:2px 0 4px}
.v56-drop-head b{font-weight:600}
.v56-drop-meta{color:#8a877d;font-size:11px;white-space:nowrap}

/* V56 – tételenkénti hátralékdátum */
.item-move-date{display:inline-flex;flex-direction:column;gap:2px;font-size:11px;color:#6b675d;margin-left:10px}
.item-move-date-input{font-size:12px;padding:3px 6px;border:.5px solid #cfcbbf;border-radius:6px;background:#fff}
.missing-qty-wrap{display:flex;align-items:flex-end;flex-wrap:wrap;gap:6px}

/* V57 – sofőri lista egy sorban */
.mobile-user-row{background:#fff;border:.5px solid #d9d5c9;border-radius:10px;padding:8px 10px;margin:0 0 8px}
.mobile-user-row.done{opacity:.6}
.v57-row-head{display:flex;align-items:center;gap:8px}
.v57-row-title{flex:1;min-width:0;font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v57-detail-toggle{flex:none;width:28px;height:28px;border:.5px solid #cfcbbf;background:#fff;border-radius:6px;cursor:pointer}
.v57-row-actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:7px}
/* Az alap button szabály fehér betűt ad (color:#fff), a soron viszont világos
   a háttér – ezért a felirat olvashatatlan volt. A gombok betűszíne ugyanaz,
   mint a felrakó/lerakó soré. */
.v57-row-actions button{flex:1 1 auto;min-height:36px;font-size:13px;font-weight:600;
  border:.5px solid #cfcbbf;background:#fff;color:var(--ink);border-radius:7px;cursor:pointer}
.v57-row-actions button:hover{background:#f4f2ec}
.v57-row-actions .camera-action{background:#e6f1fb;border-color:#85b7eb;color:var(--ink)}
.v57-row-actions .transfer-action{background:#f2ecfb;border-color:#b9a6e6;color:var(--ink)}
.v57-row-detail{margin-top:8px;padding-top:8px;border-top:.5px solid #e6e3d9}

/* V57 – hátralék nézet */
.backlog-list{display:flex;flex-direction:column;gap:14px}
.bl-day{background:#fff;border:.5px solid #d9d5c9;border-radius:10px;overflow:hidden}
.bl-day-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;
  padding:9px 12px;background:#f4f2ec;border-bottom:.5px solid #d9d5c9;font-size:14px}
.bl-day-head span{font-size:12px;color:#6b675d}
.bl-overdue{border-color:#e0a4a4}
.bl-overdue .bl-day-head{background:#fbeaea;color:#8d2b2b;border-bottom-color:#e0a4a4}
.bl-supplier{border-bottom:.5px solid #ece9e0}
.bl-supplier:last-child{border-bottom:0}
.bl-supplier-head{display:flex;justify-content:space-between;padding:7px 12px 3px;font-size:13px}
.bl-supplier-head span{color:#8a877d;font-size:11px}
.bl-item{display:flex;align-items:center;gap:8px;padding:6px 12px 8px}
.bl-item.overdue .bl-item-name,.bl-item.undated .bl-item-name{color:#8d2b2b}
.bl-item-main{flex:1;min-width:0}
.bl-item-name{font-size:13px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bl-code{font-weight:400;color:#8a877d;font-size:11px}
.bl-item-sub{font-size:11px;color:#6b675d;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bl-orphan{color:#8d2b2b}
.bl-arrived{flex:none;height:28px;padding:0 10px;font-size:12px;border:.5px solid #8fbf8f;
  background:#eaf6ea;border-radius:6px;cursor:pointer;color:#255f25}
.bl-arrived:hover{background:#d9eeda}
.bl-open{flex:none;width:28px;height:28px;border:.5px solid #cfcbbf;background:#fff;border-radius:6px;cursor:pointer}

/* V57 – tételablak négyoszlopos rácsa */
.item-grid-head,.item-grid{display:grid;grid-template-columns:26px 1fr 92px 148px;gap:10px;align-items:start}
.item-grid-head{padding:7px 12px;background:#f4f2ec;border-bottom:.5px solid #d9d5c9;
  font-size:11px;color:#6b675d;position:sticky;top:0;z-index:2}
.item-grid{padding:9px 12px;border-bottom:.5px solid #ece9e0;align-items:center}
.item-grid.done{opacity:.55}
.item-grid.done .item-name{text-decoration:line-through}
.item-main{min-width:0}
.item-main .item-name{font-size:13px;font-weight:600}
.item-sub{font-size:11px;color:#6b675d}
.item-moved{color:#0c447c}
.item-main .item-note-edit textarea{width:100%;min-height:30px;font-size:12px;margin-top:4px;
  border:.5px solid #e0ddd3;border-radius:6px;padding:4px 6px;resize:vertical}
.item-date-cell{display:flex;flex-direction:column;gap:4px}
.item-date-cell .item-move-date-input{width:100%;font-size:12px;padding:4px 6px;
  border:.5px solid #cfcbbf;border-radius:6px;background:#fff}
.item-undo{font-size:11px;padding:3px 6px;border:.5px solid #e0a4a4;background:#fbeaea;
  color:#8d2b2b;border-radius:6px;cursor:pointer}
.item-dash{color:#a5a297;font-size:12px;text-align:center}
.missing-qty-input{width:100%;font-size:13px;padding:4px 6px;border:.5px solid #cfcbbf;border-radius:6px}
@media(max-width:640px){
  .item-grid-head{display:none}
  .item-grid{grid-template-columns:24px 1fr;gap:8px}
  .item-grid>.missing-qty-input,.item-grid>.item-date-cell,.item-grid>.item-dash{grid-column:2}
}
.bl-undo{flex:none;height:28px;padding:0 9px;font-size:12px;border:.5px solid #e0a4a4;
  background:#fbeaea;color:#8d2b2b;border-radius:6px;cursor:pointer}
.bl-undo:hover{background:#f6dada}

/* V58 – a tételsor alapból letisztult, a hiány külön nyílik */
.item-shortage-btn{width:100%;font-size:12px;padding:5px 6px;border:.5px dashed #cfcbbf;
  background:#fbfaf6;color:#6b675d;border-radius:6px;cursor:pointer}
.item-shortage-btn:hover{background:#f3f0e8;border-style:solid;color:#8d2b2b;border-color:#e0a4a4}
.item-grid.shortage{background:#fdf6f3}
.item-grid.shortage .item-name{color:#8d2b2b}

/* V60 – a hiányzó mennyiség mezője legyen jól látható.
   Korábbi szabályok !important-tal 20px betűt és 48px magasságot adtak neki,
   de a rács oszlopa csak 92px volt, ezért a szám nem fért ki. */
.item-grid-head,.item-grid{grid-template-columns:26px minmax(0,1fr) 132px 168px}
.item-grid>.missing-qty-input,.item-qty-cell .missing-qty-input{
  width:100%!important;min-width:0!important;height:44px!important;
  font-size:19px!important;font-weight:700!important;text-align:center;
  padding:6px 8px!important;margin-top:0!important;
  border:1.5px solid #c9a86a!important;border-radius:8px!important;
  background:#fffaf0!important;color:#5b4a2a!important}
.item-grid>.missing-qty-input:focus,.item-qty-cell .missing-qty-input:focus{
  border-color:#a5813a!important;outline:2px solid #efd7a6;outline-offset:1px}
.item-grid>.missing-qty-input::placeholder{font-size:13px;font-weight:500;color:#a08a63}
.item-qty-cell{display:flex;flex-direction:column;gap:3px}
.item-qty-unit{font-size:11px;color:#6b675d;text-align:center}
@media(max-width:640px){
  .item-grid{grid-template-columns:24px 1fr;gap:8px}
  .item-grid>.item-qty-cell,.item-grid>.item-date-cell,.item-grid>.item-dash,
  .item-grid>.missing-qty-input{grid-column:2}
  .item-grid>.missing-qty-input,.item-qty-cell .missing-qty-input{height:48px!important;font-size:20px!important}
}

/* V60 – nagyobb, jól megfogható húzófogantyú a Nézetben */
.v56-drag{display:flex;align-items:center;justify-content:center;width:30px;height:34px;
  margin-left:-4px;font-size:19px;color:#8a877d;border-radius:7px;cursor:grab;
  touch-action:none;user-select:none}
.v56-drag:hover{background:#efece4;color:#4a4842}
.v56-drag:active{cursor:grabbing;background:#e4e0d5}
.v56-row{padding-left:6px}

/* V60 – importált levél a sofőri felületen */
.v57-row-actions .mail-action{background:#eef7ea;border-color:#a9cf9a;color:var(--ink)}
.source-mail{max-height:70vh;overflow:auto}
.mail-meta{font-size:12px;color:#5f5c54;margin:0 0 8px;display:flex;flex-direction:column;gap:2px}
.mail-body{white-space:pre-wrap;word-break:break-word;font:13px/1.5 system-ui,sans-serif;
  background:#faf9f5;border:.5px solid #e0ddd3;border-radius:8px;padding:10px;margin:0 0 10px}
.mail-files{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.mail-file{display:inline-block;padding:7px 11px;font-size:13px;border:.5px solid #85b7eb;
  background:#e6f1fb;color:#0c447c;border-radius:7px;text-decoration:none}
.mail-file:hover{background:#d4e7f8}


/* A sofőri sor egyéb elemei is örökölhetik a fehér betűt – rögzítjük. */
.v57-detail-toggle{color:var(--ink)}
.v57-row-detail button{color:var(--ink)}


/* V61 – egységes keresős lenyíló */
.combo{position:relative}
.combo-hidden-select{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}
.combo-input{width:100%;padding:8px 10px;font-size:13px;border:.5px solid #cfcbbf;
  border-radius:8px;background:#fff;color:var(--ink)}
.combo-input:focus{border-color:#85b7eb;outline:2px solid #d8e8f8;outline-offset:1px}
.combo-list{position:absolute;left:0;right:0;top:calc(100% + 3px);z-index:60;max-height:280px;
  overflow:auto;background:#fff;border:.5px solid #cfcbbf;border-radius:8px;
  box-shadow:0 10px 26px rgba(0,0,0,.16);padding:3px}
.combo-option{display:flex;justify-content:space-between;align-items:baseline;gap:10px;width:100%;
  padding:7px 9px;border:0;background:none;color:var(--ink);font-size:13px;text-align:left;
  border-radius:6px;cursor:pointer;font-weight:500}
.combo-option small{color:#8a877d;font-size:11px;white-space:nowrap;font-weight:400}
.combo-option:hover,.combo-option.active{background:#e6f1fb}
.combo-empty{padding:9px;font-size:12px;color:#8a877d}

/* V65 – kézzel felvitt tételek és a csatolmány gomb */
