/* V67 — presentation only. All V66 controls, states and event handlers retained. */
:root{--navy:#0873ed;--blue:#076fe5;--blue-2:#005ec4;--sky:#eaf3ff;--bg:#f2f6fb;--card:#fff;--ink:#152b43;--muted:#61768c;--green:#008e69;--red:#d94348;--border:#dfe8f1;--v67-teal:#008982}
body{background:var(--bg);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}
button,.file-button,.camera-button{border-radius:10px;font-weight:650}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #1689ff;outline-offset:3px}
button:disabled{opacity:.5;cursor:not-allowed}
input,select,textarea{border-color:#d7e2ee;border-radius:10px}
