.nav[data-page="planner"]{--v67-icon:var(--v67-truck)}
.nav[data-page="orders"],.nav[data-page="outlookImport"]{--v67-icon:var(--v67-document)}
.nav[data-page="driver"],.nav[data-page="online"]{--v67-icon:var(--v67-user)}
.nav[data-page="backlog"]{--v67-icon:var(--v67-clock)}
.nav[data-page="reports"]{--v67-icon:var(--v67-chart)}
.nav[data-page="vehicles"]{--v67-icon:var(--v67-truck)}
